3	/**
4	 * Membership-level rules for an owner. The level starts at 1 and gains a point for each loyalty
5	 * factor the owner meets: having an email address, having had no namesakes at creation
6	 * ({@code namesakeCount} of 0), and a tenure of more than {@link #TENURE_DAYS_FOR_TOP_LEVEL} days.
7	 *
8	 * <p>The first two factors are established at creation and so saturate at level 3; the tenure
9	 * factor is the only route to level 4. A newly created owner has zero tenure, so it can never
10	 * exceed level 3 &mdash; e.g. an owner with an email and no namesake is level 3, not 4.
11	 */
12	public final class MembershipLevel {
13	
14	    /** Days of tenure an owner must exceed to qualify for the top membership level (4). */
15	    public static final int TENURE_DAYS_FOR_TOP_LEVEL = 365;
16	
17	    private MembershipLevel() {
18	    }
19	
20	    /**
21	     * The membership level for an owner with the given loyalty factors. Level 4 requires
22	     * {@code tenureDays} greater than {@link #TENURE_DAYS_FOR_TOP_LEVEL}; the email and namesake
23	     * factors alone cannot exceed level 3.
24	     *
25	     * @param hasEmail      whether the owner has an email address
26	     * @param namesakeCount how many existing owners shared the owner's name at creation (0 earns a
27	     *                      point); {@code null} earns no point
28	     * @param tenureDays    the owner's tenure in days
29	     */
30	    public static int forOwner(boolean hasEmail, Integer namesakeCount, long tenureDays) {
31	        int level = 1;
32	        if (hasEmail) {
33	            level++;
34	        }
35	        if (Integer.valueOf(0).equals(namesakeCount)) {
36	            level++;
37	        }
38	        if (tenureDays > TENURE_DAYS_FOR_TOP_LEVEL) {
39	            level++;
40	        }
41	        return level;
42	    }
43	}
